var XWiki = (function (XWiki) {
// Start XWiki augmentation.
Object.extend(XWiki, {
  userprofile : {
    init : function(container) {
      // The DOM update events also target containers without the menu, which must not reset the current state.
      const tabsContainer = (container || $('body')).down('#user-vertical-menu');
      if (!tabsContainer) {
        return;
      }
      this.crtCategory = '';
      this.tabsContainer = tabsContainer;
      this.tabsContainer.select('.list-group-item[data-id]').each(function (tabElement) {
        tabElement.observe('click', function(event) {
          Event.stop(event);
          this.switchTab(tabElement.dataset.id, true);
        }.bindAsEventListener(this));
      }.bind(this));
      this.tabsContainer.select('.list-group-item[data-id].active').each(function (activeTab) {
        this.updateCategoryFields(activeTab.dataset.id);
        document.fire('xwiki:profile:switchedCategory', {'category' : activeTab.dataset.id});
        document.fire('xwiki:dom:refresh');
      }.bind(this));
      this.handleCancelAction();

      // History navigation through our pushed states.
      window.addEventListener('popstate', function(event) {
        if (event.state && event.state.category) {
          this.switchTab(event.state.category);
        }
      }.bindAsEventListener(this));
      // Store the initial history state so we can go back.
      history.replaceState({
        category: window.location.search.toQueryParams().category || this.crtCategory
      }, document.title, document.location.href);
    },

    switchTab : function(category, pushHistory) {
      const tab = this.tabsContainer.down('.list-group-item[data-id="' + CSS.escape(category) + '"]');
      if (!tab) {
        return;
      }
      $("user-page-content").select("div.user-page-pane").each(function(pane){
        pane.addClassName('hidden');
      });
      $(category + 'Pane').removeClassName('hidden');
      this.tabsContainer.select('.list-group-item[data-id].active').each(function(activeTab) {
        activeTab.removeClassName('active');
        activeTab.removeAttribute('aria-current');
      });
      tab.addClassName('active');
      tab.setAttribute('aria-current', 'page');
      // Expand the group of the tab when it's collapsed, e.g. when navigating through the history. Clicking the group
      // heading collapses the other groups.
      const groupHeading = tab.up('.panel').down('.panel-heading');
      if (groupHeading.hasClassName('collapsed')) {
        groupHeading.click();
      }
      this.updateCategoryFields(category);
      if (pushHistory) {
        this.updateURL(category);
      }
      document.fire('xwiki:profile:switchedCategory', {'category' : category});
      document.fire('xwiki:dom:refresh');
    },

    updateCategoryFields : function (category) {
      this.crtCategory = category;
      this.updateField('xredirect', XWiki.currentDocument.getURL('view', 'category=' + category));
      this.updateField('xcontinue', XWiki.currentDocument.getURL('edit', 'editor=inline&category=' + category));
      this.updateField('category', category);
    },

    updateURL : function (category) {
      if (history.pushState) {
        var params = window.location.search.toQueryParams();
        params.category = category;
        var newQueryString = Object.toQueryString(params);

        var newURL = window.location.protocol + '//' + window.location.host + window.location.pathname + '?' + newQueryString;
        window.history.pushState({category : category}, '', newURL);
      }
    },

    updateField : function (fieldName, value) {
      var element = $$('input[name=' + fieldName + ']');
      if (element && element.length) {
        element[0].value = value;
      }
    },

    handleCancelAction : function() {
      var elements = $$('form .buttons input[type=submit][name=action_cancel]');
      if (elements && elements.length) {
        var button = elements[0];
        Event.stopObserving(button, 'click');
        button.observe('click', function(event){
          event.stop();
          window.location = XWiki.currentDocument.getURL('view', 'category=' + this.crtCategory)
        }.bindAsEventListener(this));
      }
    }
  }
});

var init = function(event) {
  ((event && event.memo.elements) || [$('body')]).each(function(element) {
    XWiki.userprofile.init(element);
  });
  return true;
};
(XWiki.domIsLoaded && init()) || document.observe('xwiki:dom:loaded', init);
document.observe('xwiki:dom:updated', init);
// End XWiki augmentation.
return XWiki;
}(XWiki || {}));

#template("colorThemeInit.vm")
#set($tabswidth = "130px")
/* ----- User menu ----- */
#user-menu-col {
  float: left;
  width: 13em;
}

#user-profile-menu {
  margin-top: @line-height-computed / 2;
}

#avatar {

  p {
    text-align: center;
  }

  img {
    border-top: @border-width solid @list-group-border;
    border-left: @border-width solid @list-group-border;
    border-right: @border-width solid @list-group-border;
    border-bottom: 0;
    border-radius: @border-radius-base @border-radius-base 0 0;
    margin: 0 auto;
  }

  .attachment-picker {
    border-radius: @border-radius-base;
    padding: @border-width;
  }
}

/* ----- Page content ---- */
#user-page-content {
  margin-left: 14em;
}

.column h1, .column h2 {
  font-weight: bold;
  font-size: 115%;
  margin: 10px 0;
}

.column h3 {
  font-size: 110%;
}

/* For columns that don't adapt well to limited width. */
.column.min-half {
  min-width: 49.9%;
}

div.profile-section,
div.userInfo, div.userRecentChanges, div.userPreferences, div.passwordManagement, div.watchlistManagement, div.watchlistRss, div.watchlistElements, 
div.userDashboard, #dashboardPane .dashboard {
  margin: 5px 10px 10px;
  padding: 5px 10px 10px;
}

/* ----- Profile ----- */
td.recentChangesLeft, .recentChangesMoreActions {
  display: none;
}

td.recentChangesRight {
  padding: 0 !important;
}

div.profile-section,
div.userInfo, div.userRecentChanges, div.userPreferences, div.passwordManagement, div.watchlistManagement, div.watchlistRss, div.watchlistElements, 
div.userDashboard, #dashboardPane .dashboard {
  margin: 5px 10px 10px;
  padding: 5px 10px 10px;
}

div.highlighted-profile-section,
div.userInfo, div.userPreferences, div.watchlistManagement, div.userDashboard {
  background-color: $theme.backgroundSecondaryColor;
}

.userInfo a {
  word-wrap: break-word;
}

.userInfo img {
  max-width: 100%;
}

.userInfo h2 {
  font-size: larger;
  font-weight: bolder;
  margin-top: 10px;
}

div.userInfo input[type="text"], div.userInfo input[type="password"], div.userInfo textarea, div.userInfo select, div.userPreferences select {
  width: 100%;
}

div.editProfileCategory {
  float: right;
}


/* Watchlist */

#watchlistRssLink {
  background: url("$xwiki.getSkinFile('icons/xwiki/rss-medium.png')") no-repeat;
  padding-left: 18px;
  font-weight: bold;
}

span#avatarUpload {
  display: block;
  width: $tabswidth;
  position: absolute;
  font-size: 10px;
  font-weight: bold;
  background-color: white;
}



## --------------------------------------
## Network sections style
#networkPane .following ul {
  list-style-type: none;
  margin: 0;
  padding: 0;
}

#networkPane .following li {
  padding: 2px 20px 2px 2px;
}

#networkPane .following li:hover {
  background-color: $theme.highlightColor;
}

#networkPane .following img {
  float: left;
  margin-right: 5px;
}

#networkPane .following .user-info {
  float: left;
}

#networkPane .following .user-id {
  font-size: .8em;
  font-weight: 900;
}

#networkPane .following .unfollow {
  float: right;
  margin-right: -16px;
  padding: 0;
}

## --------------------------------------
## Picker style

#user-menu-col .attachment-picker {
  position: relative;
  margin: auto;
  width: 100%;
}

#user-menu-col .attachment-picker p {
  padding: 0;
  margin: 0;
}

#user-menu-col .attachment-picker .picture {
  z-index: -1;
}

#user-menu-col .attachment-picker .buttonwrapper {
  margin: 0;
}

#user-menu-col .attachment-picker {
  .buttonwrapper {
    display: flex;
    flex-flow: column;

    .button {
      .btn;
      .btn-default;
      border-radius: 0 0 @border-radius-base @border-radius-base;
      flex-grow: 1;
      margin: 0;
    }
  }
}

## --------------------------------------
## Dashboard
/* prevent the clearfloats between buttons & dashboard gadgets from clearing the tabs as well, only the buttons float */
.dashboard .clearfloats, 
.dashboard .clearfloats:after, .dashboard .clearfloats:before {
  clear: right;
}
